from typing import Callable
Gauge = Callable[[float], float]

def linear_gauge(L: float) -> Gauge:
    return lambda t: (L**2) * t

def compose(g: Gauge, f: Gauge) -> Gauge:
    return lambda t: g(f(t))

def iterate(eta: Gauge, n: int) -> Gauge:
    def g(t):
        for _ in range(n):
            t = eta(t)
        return t
    return g

eta = linear_gauge(1.5)   # 2.25 t
print('enlargement 2.25t <= 3t :', all(eta(t) <= 3*t+1e-12 for t in [.25,.5,1,2,4]))
print('eccentricity eta(1) =', eta(1.0))
print('compose (4t).(2.25t) at 1 =', compose(linear_gauge(2.0), eta)(1.0))
for n in range(5):
    print(f'eta^[{n}](1) =', iterate(eta, n)(1.0), ' = 2.25^', n, '=', 2.25**n)

