function BOX_COUNT_DIM(points, scales):
    X <- [], Y <- []
    for eps in scales:
        cells <- { floor(p / eps) : p in points }
        if |cells| > 0:
            X.append(log(1/eps)); Y.append(log(|cells|))
    return LEAST_SQUARES_SLOPE(X, Y)

function CHECK_INVARIANCE(points, phi, scales):
    d0 <- BOX_COUNT_DIM(points, scales)
    img <- [ phi(p) for p in points ]
    d1 <- BOX_COUNT_DIM(img, rescale(scales, phi))
    return |d0 - d1|   // ~ 0
